INSERT INTO `publications` VALUES (1,'Initial seed publish','{\"version\":1,\"built_at\":\"2026-11-09T14:16:57+00:00\",\"strings\":{\"en\":{\"about.aria\":\"About\",\"about.eyebrow\":\"About\",\"about.meta.education.label\":\"Education:\",\"about.meta.education.value\":\"B.Sc. Computer Science, Amirkabir University of Technology\",\"about.meta.location.label\":\"Location:\",\"about.meta.location.value\":\"Tehran, Iran\",\"about.meta.status.label\":\"Status:\",\"about.meta.status.value\":\"Available for freelance\",\"about.p1\":\"I\\u2019m Amirhossein Zamanzade, a Computer Science student and Full-Stack Developer focused on fast, scalable, and user-centric products. I care about clean architecture, modern tooling, and interfaces that feel refined.\",\"about.p2\":\"This portfolio reflects my learning journey across web, desktop, APIs, and automation \\u2014 and a place to connect for collaboration.\",\"about.portrait.alt\":\"Portrait of Amirhossein Zamanzade\",\"about.skills\":\"Skills\",\"about.title\":\"Software engineer.\",\"category.APIs & Backend\":\"APIs & Backend\",\"category.Applications\":\"Applications\",\"category.Automation \\/ Bots\":\"Automation \\/ Bots\",\"category.Websites\":\"Websites\",\"contact.aria\":\"Contact\",\"contact.downloadCv\":\"Download CV\",\"contact.emailMe\":\"Email me\",\"contact.eyebrow\":\"Let\\u2019s connect\",\"contact.github\":\"GitHub\",\"contact.github.sub\":\"Code & repositories\",\"contact.intro\":\"Have a project or a role in mind? Let\\u2019s talk.\",\"contact.linkedin\":\"LinkedIn\",\"contact.linkedin.sub\":\"Start a conversation\",\"contact.note\":\"Available for freelance collaborations.\",\"contact.telegram\":\"Telegram\",\"contact.telegram.sub\":\"Quick chat \\u00b7 @Amir_dev00\",\"contact.title\":\"Let\\u2019s talk.\",\"home.arrows\":\"Project slides\",\"home.next\":\"Next project\",\"home.prev\":\"Previous project\",\"home.profile.aria\":\"Amirhossein Zamanzade, Software Engineer\",\"home.profile.role\":\"Software En