INSERT INTO `seo_entries` VALUES (1,'en','page','home','Amirhossein Zamanzade | Developer','Portfolio of Amirhossein Zamanzade — Full-Stack Developer, Programmer, and Designer.','assets/img/amir/az-logo.webp','index,follow',0,'2026-11-09 10:46:57','2026-11-10 13:17:47'),(2,'fa','page','home','امیرحسین زمان‌زاده | توسعه‌دهنده','نمونه‌کارهای امیرحسین زمان‌زاده — توسعه‌دهنده فول‌استک، برنامه‌نویس و طراح.','assets/img/amir/az-logo.webp','index,follow',0,'2026-11-09 10:46:57','2026-11-10 13:17:47'),(3,'en','page','work','Work — Amirhossein Zamanzade | Developer','A selection of websites, applications, APIs, and automation tools.','assets/img/amir/az-logo.webp','index,follow',0,'2026-11-09 10:46:57','2026-11-10 13:17:47'),(4,'fa','page','work','کارها — امیرحسین زمان‌زاده | توسعه‌دهنده','گزیده‌ای از وب‌سایت‌ها، اپلیکیشن‌ها، APIها و ابزارهای اتوماسیون.','assets/img/amir/az-logo.webp','index,follow',0,'2026-11-09 10:46:57','2026-11-10 13:17:47'),(5,'en','page','about','About — Amirhossein Zamanzade | Developer','I’m Amirhossein Zamanzade, a Computer Science student and Full-Stack Developer focused on fast, scalable, and user-centric products. I care about clean architecture, modern tooling, and interfaces that feel refined.','assets/img/amir/az-logo.webp','index,follow',0,'2026-11-09 10:46:57','2026-11-10 13:17:47'),(6,'fa','page','about','درباره — امیرحسین زمان‌زاده | توسعه‌دهنده','من امیرحسین زمان‌زاده‌ام؛ دانشجوی علوم کامپیوتر و توسعه‌دهنده فول‌استک. روی محصولاتی سریع، مقیاس‌پذیر و کاربرمحور تمرکز می‌کنم و به معماری تمیز، ابزارهای مدرن و رابط‌هایی با حس پرداخت‌شده اهمیت می‌دهم.','assets/img/amir/az-logo.webp','index,follow',0,'2026-11-09 10:46:57','2026-11-10 13:17:47'),(7,'en','page','contact','Contact — Amirhossein Zamanzade | Developer','Have a project or a role in mind? Let’s talk.','assets/img/amir/az-logo.webp','index,follow',0,'2026-11-09 10:46:57','2026-11-10 13:17:47'),(8,'fa','page','contact','تماس — امیرحسین زمان‌زاده | توسعه‌دهنده','پروژه یا موقعیتی در ذهن دار